import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"迈克·沙利文","description":"","frontmatter":{"title":"迈克·沙利文","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/迈克·沙利文.md","filePath":"04_people/迈克·沙利文.md"}'),o={name:"04_people/迈克·沙利文.md"};function i(n,a,s,_,h,d){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="迈克·沙利文" tabindex="-1">迈克·沙利文 <a class="header-anchor" href="#迈克·沙利文" aria-label="Permalink to &quot;迈克·沙利文&quot;">​</a></h1><ul><li><strong>角色职位</strong>：国际乳品皇后（International Dairy Queen）CEO</li><li><strong>与巴菲特关系</strong>：被伯克希尔·哈撒韦收购的子公司 CEO</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>迈克·沙利文曾担任国际乳品皇后（International Dairy Queen）的 CEO。DQ 是全球知名的冰淇淋连锁品牌，以暴风雪（Blizzard）等特色产品著称，在数十个国家拥有数千家特许经营门店。作为 CEO，沙利文负责这家拥有强大品牌资产的跨国连锁企业的战略规划与运营管理。</p><p>在沙利文的领导下，国际乳品皇后延续了 DQ 品牌在消费者心中的地位，同时持续优化特许经营体系。DQ 的商业模式以稳定的特许权使用费收入为核心，具有良好的现金流特征，这与巴菲特一贯偏爱的&quot;拥有护城河的优质消费品牌&quot;高度吻合。</p><p>伯克希尔·哈撒韦收购国际乳品皇后后，沙利文继续发挥其管理才能，推动 DQ 在全球市场的平稳运营。巴菲特对 DQ 的投资既看中了品牌本身的持久价值，也信任沙利文及其团队的执行能力。这种&quot;以合理价格收购优秀企业并保留原管理团队&quot;的策略，是伯克希尔投资哲学在餐饮消费领域的典型体现。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>CEO 任职期</strong>：担任国际乳品皇后 CEO，主导公司在全球范围内的业务运营与扩展</li><li><strong>伯克希尔收购</strong>：国际乳品皇后被伯克希尔·哈撒韦收购，沙利文在过渡期扮演重要角色</li><li><strong>后续经营期</strong>：在伯克希尔控股下继续引领 DQ 品牌发展，保持特许经营体系的稳定运转</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=迈克·沙利文在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li><li><a href="/search.html?q=迈克·沙利文在2006年股东信中的原话">2006年：完整翻译|/01_letters/2006年/翻译</a></li><li><a href="/search.html?q=迈克·沙利文在2012年股东信中的原话">2012年：完整翻译|/01_letters/2012年/翻译</a></li></ul>',11)])])}const c=e(o,[["render",i]]);export{u as __pageData,c as default};
